"""Tails VRChat's output_log (Proton prefix) to spot FBT calibration.

Needs VRChat's IK Debug Logging on. Calibration mode start/end lines (below) freeze the trackers on the ideal T-pose
and release them; other IK lines are copied to our log.
"""
import re
from pathlib import Path

VRCHAT_LOGS = "steamapps/compatdata/438100/pfx/drive_c/users/steamuser/AppData/LocalLow/VRChat/VRChat"


def steam_libraries():
    """Every Steam library folder (VRChat's Proton prefix lives in the one it is installed in)."""
    roots = [Path.home() / ".local/share/Steam", Path.home() / ".steam/steam",
             Path.home() / ".var/app/com.valvesoftware.Steam/.local/share/Steam"]
    libs = []
    for root in roots:
        vdf = root / "steamapps/libraryfolders.vdf"
        try:
            libs += [Path(p) for p in re.findall(r'"path"\s+"([^"]+)"', vdf.read_text())]
        except OSError:
            pass
        libs.append(root)
    return libs


def find_log_dir():
    for lib in steam_libraries():
        d = lib / VRCHAT_LOGS
        if d.is_dir():
            return d
    return None
INTERESTING = re.compile(r"calibrat|\[IK|IKDebug|FBT|FBIK", re.I)
# Seen 2026-10-20 (VRChat 2026.3.3, IK Debug Logging on). Pressing "Calibrate FBT" logs
#   [VRCTrackingManager] [IK Debug Log] Calibrate FBT and reload avatar...
#   [VRCTrackingManager] [IK Debug Log] Preparing for calibration...
#   ... trigger pulled ...
#   [VRCTrackingManager] [IK Debug Log] Restore tracking...
# Not "Setting controller ... visibility": VRChat logs that on every menu open too.
START = re.compile(r"\[IK Debug Log\] (Calibrate FBT and reload avatar|Preparing for calibration)\.\.\.")
END = re.compile(r"\[IK Debug Log\] Restore tracking\.\.\.")
# "Changed player height... tracking scale:0.6480417 eye height:1.624643" (2026-10-24): the eye
# height VRChat hangs the avatar from, taken from its "Real height" setting (1.73 m → 1.6246).
HEIGHT = re.compile(r"Changed player height\.\.\. tracking scale:\s*[\d.]+ eye height:\s*([\d.]+)")


class VrchatLogWatcher:
    def __init__(self, on_start, on_end, log, on_height=None):
        self.on_start = on_start
        self.on_end = on_end
        self.on_height = on_height or (lambda eye: None)
        self.log = log
        self.log_dir = None
        self.path = None
        self.pos = 0

    def poll(self):
        if self.log_dir is None:
            self.log_dir = find_log_dir()
            if self.log_dir is None:
                return
        try:
            newest = max(self.log_dir.glob("output_log_*.txt"), key=lambda p: p.stat().st_mtime)
        except (ValueError, OSError):
            return
        if newest != self.path:
            self.path = newest
            self.pos = newest.stat().st_size  # only new lines
            self.last_height()
        try:
            with open(self.path, "rb") as f:
                f.seek(self.pos)
                data = f.read()
        except OSError:
            return
        if not data:
            return
        cut = data.rfind(b"\n") + 1
        self.pos += cut
        for line in data[:cut].decode("utf-8", "replace").splitlines():
            if INTERESTING.search(line) and "Selfie Expression" not in line:
                self.log("vrchat: " + line.strip()[:300])
            m = HEIGHT.search(line)
            if m:
                self.on_height(float(m.group(1)))
            if START.search(line):
                self.on_start()
            elif END.search(line):
                self.on_end()

    def last_height(self):
        """VRChat logs the height once per avatar load: pick up the latest one already written."""
        try:
            with open(self.path, "rb") as f:
                f.seek(max(0, self.pos - 4_000_000))
                tail = f.read(self.pos - f.tell()).decode("utf-8", "replace")
        except OSError:
            return
        found = HEIGHT.findall(tail)
        if found:
            self.on_height(float(found[-1]))
